def solve(inputs: dict) -> float:
    M = inputs['M']
    power = inputs['power']
    modulo = inputs['modulo']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, p, mod):
        """Compute M^p modulo mod using fast exponentiation"""
        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while p > 0:
            if p % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            p //= 2

        return result

    result_matrix = matrix_pow(M, power, modulo)

    # Sum all four entries
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return total % modulo
